    private static readonly Regex bribe=new(@"\b(in return|for a favou?r|so that you|so you('ll| will| can)|if you (tell|say|let|keep|forget|look|help|do)|keep (quiet|mum|your mouth)|say nothing|look the other way|won't tell|not a word|bribe|between us)\b",RegexOptions.IgnoreCase);
    private static readonly Regex give=new(@"\b(give|giving|gift|present|(?<!\b(do|did|can|could|would|will) you |you |i )have (this|it|my|a|an|the|some|another|one|these|more)|(?<!\b(can|may|could|shall) i |let me |i'?ll |i will |i )take (this|it|my|a|an|the|some|another|one|these|more)|(would you like|do you want|you want) (a|an|some|my|this)|for you|brought you|here'?s|here is|keep (it|this)|yours|a little something|spare you)\b",RegexOptions.IgnoreCase);
    private static readonly Regex flattery=new(@"\b(beautiful|lovely|handsome|finest|best (man|woman|lady|fellow|seller) in|so (kind|wise|clever|pretty)|my (dear|friend|darling))\b",RegexOptions.IgnoreCase);
