    private bool Food(string kind)=>S(host.Trade.Item(kind),"use")=="eat"&&host.Trade.Item(kind)?["atCounter"]?.GetValue<bool>()!=true;
    public double Felt(JsonObject resident,string kind,int foodToday=0)
    {
        double wealth=N(resident["stats"],"wealth"),need=1,piety=N(resident["stats"],"piety");string trade=S(resident,"trade");if(Food(kind)){double hunger=trade is "beggar"or"street_child"?2.5:wealth<=1?1.8:wealth<=3?1.3:wealth<=6?1:.6;need=hunger*Math.Pow(.5,foodToday);}else if(kind=="lantern")need=new[]{"lamplighter","police","water_bailiff","docker","boatman","natie","sailor","customs"}.Contains(trade)?1.5:N(resident,"age")<13?.5:1;else if(kind is "jenever"or"beer")need=piety>=8?.2:1;else if(kind is "rosary"or"candle"or"holy_picture")need=piety>=7?1.5:piety<=2?.4:1;else if(kind is "coal"or"scarf")need=wealth<=2?1.5:.8;return N(deeds.Data["giftValues"],kind)*need/(1+wealth*.35);
