    }
    public int GiveTrust(int player,JsonObject resident,double felt,bool food,double mood=1)
    {
        string id=S(resident,"id"),key=Day+":"+id;C.Execute("INSERT OR IGNORE INTO npc_relationship(npc_id,player_id) VALUES($p0,$p1)",id,player);var ledger=Ledger(player);var today=ledger["days"]?[key]as JsonObject??new JsonObject{["n"]=0,["food"]=0};int n=(int)N(today,"n");double diminish=n==0?1:n==1?.4:n==2?.15:0;today["n"]=n+1;if(food)today["food"]=N(today,"food")+1;ledger["days"]![key]=today;int points=0;if(felt>=3&&diminish>0){double credit=N(ledger["credit"],id)+Math.Min(2,felt/6)*diminish*mood;int whole=(int)Math.Floor(credit+1e-9),trust=C.Scalar<int>("SELECT trust FROM npc_relationship WHERE npc_id=$p0 AND player_id=$p1",id,player),room=(int)Math.Max(0,Math.Min(2-N(ledger["gained"],id),6-trust));points=Math.Max(0,Math.Min(whole,room));ledger["credit"]![id]=points<whole?0:credit-whole;if(points>0){ledger["gained"]![id]=N(ledger["gained"],id)+points;C.Execute("UPDATE npc_relationship SET trust=MAX(-5,MIN(10,trust+$p0)) WHERE npc_id=$p1 AND player_id=$p2",points,id,player);}}C.SetPlayerState(player,"gifts:ledger",ledger);return points;
    }
    private string[] Kinds(string text)
    {
        var list=deeds.Data["giftValues"]!.AsObject().Select(p=>p.Key).Where(k=>Regex.IsMatch(text,@"\b"+Regex.Escape(k)+@"s?\b",RegexOptions.IgnoreCase)).ToList();foreach(var alias in new[]{("fish",new[]{"herring","eel"}),("loaf|loaves|rye",new[]{"bread"}),("lamp|light",new[]{"lantern"}),("food|something to eat|a bite|a meal",new[]{"bread","eel","herring","mussels","biscuit","roll","apple"}),("paper|handelsblad",new[]{"newspaper"}),("gin|genever",new[]{"jenever"})})if(Regex.IsMatch(text,@"\b("+alias.Item1+@")\b",RegexOptions.IgnoreCase))foreach(string kind in alias.Item2)if(!list.Contains(kind))list.Add(kind);return list.ToArray();
    }
    public JsonObject Give(int player,JsonObject resident,string words,string modelItem="")=>C.Atomic(()=>
    {
        string id=S(resident,"id");JsonObject No(string reason,string line)=>new(){["ok"]=false,["reason"]=reason,["line"]=line,["note"]="",["trust"]=0,["felt"]=0,["held"]=null};var said=Kinds(words);var narrowed=Kinds(modelItem).Where(said.Contains).ToArray();var kinds=narrowed.Length>0?narrowed:said;var held=C.Rows("SELECT id,kind,job_id,ref FROM item WHERE player_id=$p0 ORDER BY id",player);foreach(var piece in C.Rows("SELECT id,kind FROM home_item WHERE player_id=$p0 AND state='arms'",player)){piece!["from"]="arms";piece["job_id"]=null;piece["ref"]=piece["id"]!.DeepClone();held.Add(piece.DeepClone());}var h=kinds.Select(k=>held.FirstOrDefault(i=>S(i,"kind")==k)).FirstOrDefault(i=>i!=null);if(h==null)return No(Regex.IsMatch(words,"money|coins?|centimes?|francs?",RegexOptions.IgnoreCase)?"money":"no_item","Keep your money. You have nothing like that to give.");string kind=S(h,"kind");if(h["job_id"]!=null||new[]{"parcel","letters","letter","pawn_ticket","diary","found","velocipede_new","velocipede_used","velocipede_hire"}.Contains(kind)||deeds.Data["giftValues"]?[kind]==null)return No("not_giftable","That is not yours to give away.");
        var stolen=S(h,"from")=="arms"?null:C.One("SELECT * FROM deed WHERE item_id=$p0 AND player_id=$p1 AND status='open' ORDER BY id DESC LIMIT 1",(int)N(h,"id"),player);bool knows=stolen!=null&&(S(stolen,"owner")==id&&N(stolen,"owner_saw")>0||A(JsonNode.Parse(S(stolen,"witnesses","[]"))).Any(w=>w is JsonValue v&&v.TryGetValue<string>(out var text)?text==id:S(w,"id")==id));if(knows&&S(stolen,"owner")==id){deeds.Return(player,(int)N(stolen,"id"));var back=No("own_back","That is mine. I will have it back, thank you.");back["held"]=h.DeepClone();back["handover"]=new JsonObject{["item"]=kind,["name"]=S(host.Trade.Item(kind),"name",kind),["eaten"]=false,["warmed"]=false};return back;}
        bool duty=new[]{"police","water_bailiff","customs","sentry","corporal"}.Contains(S(resident,"trade"))&&host.Trade.AtWork(id);if(duty)return No("on_duty","Put that away. I am on duty, and take nothing from anyone.");int trust=C.Scalar<int>("SELECT trust FROM npc_relationship WHERE npc_id=$p0 AND player_id=$p1",id,player);bool isBribe=bribe.IsMatch(words),isFlattery=flattery.IsMatch(words),dislike=trust<0&&(N(resident["stats"],"temper")>=6||trust<=-3||isBribe||isFlattery);string? refusal=knows?"stolen":dislike?"dislike":isBribe&&N(resident["stats"],"honesty")>=7?"bribe":null;if(refusal!=null){if(refusal is "stolen"or"bribe"||dislike&&(isBribe||isFlattery)){C.Execute("INSERT OR IGNORE INTO npc_relationship(npc_id,player_id) VALUES($p0,$p1)",id,player);C.Execute("UPDATE npc_relationship SET trust=MAX(-5,trust-1) WHERE npc_id=$p0 AND player_id=$p1",id,player);host.Trade.Remember(player,id,"Jef tried to sweeten me with a present, as if I would forget.",5);}return No(refusal,refusal=="stolen"?"That is stolen. I saw you take it.":refusal=="bribe"?"I will not be bought.":"I want nothing from you.");}
        var today=Ledger(player)["days"]?[Day+":"+id];double felt=Felt(resident,kind,(int)N(today,"food"));bool proud=N(resident["stats"],"wealth")>=6||N(resident["stats"],"wealth")>=4&&N(resident["stats"],"temper")>=7;if(proud&&felt<3)return No("pride","Keep it. You need it more than I do.");if(N(today,"n")>=3)return No("enough_today","No more. You have given me plenty today.");bool eaten=Food(kind)&&(N(resident,"age")<13||S(resident,"trade")is "beggar"or"street_child"&&N(today,"food")==0);if(S(h,"from")=="arms")C.Execute("UPDATE home_item SET state='gone' WHERE id=$p0 AND player_id=$p1",(int)N(h,"id"),player);else{C.Execute("DELETE FROM item WHERE id=$p0 AND player_id=$p1",(int)N(h,"id"),player);if(h["ref"]!=null)C.Execute("UPDATE home_item SET state='gone' WHERE id=$p0 AND player_id=$p1",(int)N(h,"ref"),player);}int gained=GiveTrust(player,resident,felt,Food(kind),trust<0?.5:1);string name=S(host.Trade.Item(kind),"name",kind);C.Log(player,"gave",id,$"Jef gave {S(resident,"name")} {name}.");host.Trade.Remember(player,id,"Jef gave me "+name+(eaten?", and I ate it there and then.":"."),felt>=3?Math.Min(6,3+gained):2,felt>=3?$"Jef gave {S(resident,"name")} {name}":null,felt>=3?1:0);return new JsonObject{["ok"]=true,["reason"]="accepted",["line"]=eaten?"For me? Thank you. I have not eaten since morning.":"That is good of you. Thank you.",["note"]=gained>0?"They seem touched.":"They take it gladly enough.",["trust"]=gained,["felt"]=felt,["eaten"]=eaten,["held"]=h!.DeepClone(),["handover"]=new JsonObject{["item"]=kind,["name"]=name,["eaten"]=eaten,["warmed"]=gained>0}};
    });
    public JsonObject? Propose(int player,JsonObject resident,JsonObject proposal)
    {
        string words=S(proposal,"asked_words",S(proposal,"reason"));if(!give.IsMatch(words))return new(){["action_id"]=null,["refused"]=null,["line"]=""};var result=Give(player,resident,words,S(proposal,"item"));result["action_id"]=null;result["refused"]=result["ok"]?.GetValue<bool>()==true?null:JsonValue.Create("gift");host.PublishState(player);return result;
    }
    public void AttachTalk(NativeTownTalk talk)=>talk.EngineFreeReplies.Add((request,person,words)=>{if(talk.CanNarrate(request.PlayerId,S(person,"id"))||!OffersGift(words))return null;var result=Give(request.PlayerId,person,words);var answer=talk.Line(request,person,S(result,"line"));foreach(string field in new[]{"note","handover"})if(result[field]!=null)answer[field]=result[field]!.DeepClone();host.PublishState(request.PlayerId);return answer;});
